mapper.select:
SELECT p.id, p.user_id AS userId, p.title, p.content, p.images, p.like_count AS likeCount, p.collect_count AS collectCount, p.is_top AS isTop, p.is_essence AS isEssence, p.create_time AS createTime, p.update_time AS updateTime, u.username AS userName, u.avatar AS userAvatar, (SELECT COUNT(1) FROM post_reply r WHERE r.post_id = p.id AND r.is_deleted = 0) AS replyCount FROM forum_post p LEFT JOIN user_info u ON p.user_id = u.id WHERE p.is_deleted = 0
AND (p.title LIKE CONCAT('%', #{query.keyword}, '%') OR p.content LIKE CONCAT('%', #{query.keyword}, '%'))
AND p.user_id = #{query.userId}
AND p.is_top = #{query.isTop}
AND p.is_essence = #{query.isEssence}
AND p.create_time >= #{query.startTime}
AND p.create_time <= #{query.endTime}
ORDER BY p.is_top DESC, p.create_time DESC

